/* Contact Page - Hero Section */
.contact-hero {
  background: linear-gradient(135deg, var(--color-primary-light) 0%, var(--color-gray-bg) 100%);
  padding: var(--spacing-xl) var(--spacing-md);
  text-align: center;
  border-bottom: 3px solid var(--color-primary-dark);
}

.contact-hero h1 {
  margin-bottom: var(--spacing-md);
}

.contact-hero-subtitle {
  font-size: 1.1rem;
  color: var(--color-text);
  max-width: 600px;
  margin: 0 auto;
  font-weight: 500;
}

/* Hours Section */
.contact-hours {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: var(--color-text-light);
}

.contact-hours h2 {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.hours-grid {
  display: grid;
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
}

.hours-card {
  text-align: center;
  background-color: var(--color-primary-light);
  border: 2px solid var(--color-primary-dark);
}

.hours-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.hours-time {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 0;
}

.hours-note {
  background-color: var(--color-gray-bg);
  padding: var(--spacing-md);
  border-left: 4px solid var(--color-accent-dark);
  border-radius: var(--radius);
  font-size: 0.95rem;
  margin-bottom: 0;
}

/* Contact Form Section */
.contact-form-section {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: var(--color-text-light);
}

.contact-form-section h2 {
  text-align: center;
  margin-bottom: var(--spacing-md);
}

.contact-form-section > .container > p {
  text-align: center;
  color: var(--color-text);
  margin-bottom: var(--spacing-lg);
}

.contact-form {
  max-width: 600px;
  margin: 0 auto;
  background-color: var(--color-gray-bg);
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  border: 1px solid var(--color-border);
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.form-group label {
  color: var(--color-text);
}

.form-group input,
.form-group textarea {
  border: 2px solid var(--color-border);
}

.form-group input:focus,
.form-group textarea:focus {
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(155, 44, 28, 0.1);
}

.btn-submit {
  display: block;
  margin: var(--spacing-lg) auto 0;
  min-height: 44px;
  padding: var(--spacing-md) var(--spacing-lg);
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  transition: background-color 0.3s ease, transform 0.2s ease;
  width: auto;
}

.btn-submit:hover {
  background-color: var(--color-accent-dark);
  transform: translateY(-2px);
}

.btn-submit:active {
  transform: translateY(0);
}

.btn-submit:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

/* Contact Info Section */
.contact-info {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: var(--color-primary-light);
  border-top: 3px solid var(--color-primary-dark);
}

.contact-info h2 {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.info-grid {
  display: grid;
  gap: var(--spacing-lg);
}

.info-card {
  background-color: var(--color-text-light);
  border: 2px solid var(--color-border);
  padding: var(--spacing-lg);
}

.info-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
  font-size: 1.2rem;
}

.info-card p {
  margin-bottom: var(--spacing-sm);
  font-size: 1rem;
}

.info-card p:last-child {
  margin-bottom: 0;
}

.info-card a {
  color: var(--color-primary-dark);
  font-weight: 600;
  text-decoration: none;
}

.info-card a:hover {
  color: var(--color-accent-dark);
  text-decoration: underline;
}

.info-small {
  font-size: 0.9rem;
  color: #666;
  margin-bottom: 0 !important;
}

/* Desktop Breakpoint */
@media (min-width: 601px) {
  .contact-hero {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .contact-hours {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .hours-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .contact-form-section {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .contact-info {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .info-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Mobile Breakpoint */
@media (max-width: 600px) {
  .contact-hero {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .contact-hero-subtitle {
    font-size: 1rem;
  }

  .contact-hours {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .hours-grid {
    grid-template-columns: 1fr;
  }

  .contact-form-section {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .contact-form {
    padding: var(--spacing-md);
  }

  .btn-submit {
    width: 100%;
    margin: var(--spacing-md) auto 0;
  }

  .contact-info {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .info-grid {
    grid-template-columns: 1fr;
  }

  .info-card {
    padding: var(--spacing-md);
  }
}

